solution.code:
function once(fn) {
  let called = false;
  let result;
  return function (...args) {
    if (!called) { called = true; result = fn.apply(this, args); }
    return result;
  };
}

const init = once(() => { console.log('init ran'); return 42; });
console.log(init());
console.log(init());

