solution.code:
for (let i = 0; i < 3; i++) {
  setTimeout(function () {
    console.log(i);
  }, 10);
}
// let is block-scoped: each iteration gets a fresh i -> 0,1,2

function debounce(fn, delay) {
  let timer;
  return function (...args) {
    clearTimeout(timer);
    timer = setTimeout(() => fn.apply(this, args), delay);
  };
}
